arguments.command:
mkdir -p tests/CheckoutPricing.UnitTests/Checkout
cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    public decimal Handle(string customerTier, decimal orderSubtotal) => orderSubtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var payable = new CalculatePayableTotal().Handle("Gold", 100.00m);

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | tail -20

